#include "atree.hpp"

#include <complex>
#include <string>
#include <FArray.hpp>
#include <W1jet.hpp>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>

using namespace mxpart_mod;
using namespace sprods_com_mod;

//---- the basic process is atreepp which is the amplitude for
//---- q-(p4)+Q(-p2)+l-(-p5) ---> q+(p1)+Q-(p3)+l+(p6)
//---- All outgoing particles are right-handed,
//---- except Q(p3) which is left-handed
std::complex<double> atree(const std::string& st, int j1, int j2, int j3, int j4, int j5, int j6,
                           FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  std::complex<double> atree_res(0.0, 0.0);

  // Statement function for pp (others derived by crossing); BDKW Eq.(3.10)
  auto tree = [&za, &zb](int k1, int k2, int k3, int k4, int k5, int k6) {
    return zb(k1,k2)*za(k5,k4)*(za(k3,k1)*zb(k1,k6) + za(k3,k2)*zb(k2,k6))
             / (s(k2,k3)*s(k5,k6)*t(k1,k2,k3))
         + za(k3,k4)*zb(k6,k1)*(za(k5,k3)*zb(k3,k2) + za(k5,k4)*zb(k4,k2))
             / (s(k2,k3)*s(k5,k6)*t(k2,k3,k4));
  };

  if (st == "pp") {
    atree_res = +tree(j1,j2,j3,j4,j5,j6);
  } else if (st == "pm") {
    atree_res = -tree(j1,j3,j2,j4,j5,j6);
  } else if (st == "sl") {
    // this is not a real tree amplitude but it is an auxiliary quantity.
    atree_res = -tree(j3,j1,j2,j4,j5,j6);
  }

  std::complex<double> atree_out = atree_res;  // @coverage-probe
  return atree_out;
}

extern "C" {
  std::complex<double> atree_wrapper(const char* st, int j1, int j2, int j3, int j4, int j5, int j6,
                                     std::complex<double>* fza, std::complex<double>* fzb) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    return atree(std::string(st, 2), j1, j2, j3, j4, j5, j6, za, zb);
  }
}

