#include "ZZbox1LL.hpp"

#include <complex>
#include <FArray.hpp>
#include <constants_mod.hpp>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>

using namespace constants_mod;
using namespace mxpart_mod;
using namespace sprods_com_mod;

//-----Author: R.K. Ellis (September 2013)
//-----Box coefficient for LL coupling
//-----Box D0(p1,p34,p2,mt,mt,mt,mt)
//-----Opposite off-shellnesses: so called easy box
//-----Xpp and Xmp refer to the initial state gluon polarizations
// Only ZZbox1LL calls this, so it stays local to this translation unit.
static void ZZbox1LLcore(int j1, int j2, int j3, int j4, int j5, int j6,
                         FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb,
                         double mt,
                         FArray2D<std::complex<double>>& Xpp, FArray2D<std::complex<double>>& Xmp,
                         FArray4D<std::complex<double>>& Xrat) {

  // statement functions
  auto zab2 = [&za, &zb](int k1, int k2, int k3, int k4) {
    return za(k1,k2)*zb(k2,k4) + za(k1,k3)*zb(k3,k4);
  };
  auto funcpp2 = [&za, &zb, &zab2](int k1, int k2, int k3, int k4, int k5, int k6) {
    return -half*(
        + za(k1,k3)*za(k2,k5)*za(k3,k4)*zb(k4,k2)*zb(k4,k3)*zb(k6,k1)
        + za(k1,k3)*za(k1,k5)*za(k2,k3)*zb(k2,k1)*zb(k4,k3)*zb(k6,k1)
        - za(k1,k2)*za(k3,k4)*za(k3,k5)*zb(k4,k2)*zb(k4,k3)*zb(k6,k1)
        - za(k1,k5)*za(k2,k3)*zab2(k5,k3,k4,k2)*zb(k4,k1)*zb(k6,k5)
        - 4.0*(za(k1,k5)*za(k2,k3))*(za(k1,k5)*za(k2,k3))
              *zb(k2,k1)*zb(k4,k3)*zb(k6,k5)/za(k1,k2)
        - za(k1,k3)*za(k2,k5)*za(k3,k5)*zb(k2,k1)*zb(k4,k3)*zb(k6,k5)
        + za(k1,k2)*za(k3,k5)*za(k3,k5)*zb(k2,k1)*zb(k4,k3)*zb(k6,k5))
      / (za(k1,k2)*za(k1,k2)*s(k3,k4)*s(k5,k6));
  };
  auto funcmp2 = [&za, &zb, &zab2](int k1, int k2, int k3, int k4, int k5, int k6) {
    return half*(
        - za(k5,k6)*zab2(k1,k3,k4,k2)*zab2(k3,k2,k4,k1)
          *zb(k4,k1)*zb(k6,k2)*zb(k6,k2)/(zab2(k2,k3,k4,k1)*zb(k2,k1)*zb(k2,k1))
        + za(k1,k5)*za(k1,k5)*za(k2,k3)
          *zab2(k1,k3,k4,k2)*zab2(k2,k1,k3,k4)*zb(k6,k5)
          /(za(k1,k2)*za(k1,k2)*zab2(k2,k3,k4,k1)))/(s(k3,k4)*s(k5,k6));
  };
  // end statement functions

  double mtsq = mt*mt;

  int k1 = j1;
  int k2 = j2;
  for (int h3 = 1; h3 <= 2; ++h3) {
    int k3, k4;
    if (h3 == 1) { k3 = j3; k4 = j4; } else { k3 = j4; k4 = j3; }
    for (int h5 = 1; h5 <= 2; ++h5) {
      int k5, k6;
      if (h5 == 1) { k5 = j5; k6 = j6; } else { k5 = j6; k6 = j5; }

      double s134 = s(k1,k3) + s(k1,k4) + s(k3,k4);
      double s234 = s(k2,k3) + s(k2,k4) + s(k3,k4);

      //----Helicity 1^+ 2^+
      std::complex<double> app0 = half*(two*za(k3,k2)*za(k3,k1)*za(k2,k5)*za(k1,k5)
          + (za(k3,k5)*za(k1,k2))*(za(k3,k5)*za(k1,k2)))*(s134*s234 - s(k3,k4)*s(k5,k6))
          / (za(k1,k2)*za(k1,k2)*za(k1,k2)*za(k1,k2)*za(k3,k4)*za(k5,k6));

      std::complex<double> app2 = funcpp2(k1,k2,k3,k4,k5,k6) + funcpp2(k2,k1,k3,k4,k5,k6);

      std::complex<double> app4 = two/(s(k3,k4)*s(k5,k6)*za(k1,k2)*za(k1,k2))
          * (zb(k4,k1)*zab2(k1,k3,k4,k2)*za(k2,k5)
             - zb(k4,k2)*zab2(k2,k3,k4,k1)*za(k1,k5))
          * (za(k1,k3)*zb(k6,k2)/zab2(k1,k3,k4,k2)
             - za(k2,k3)*zb(k6,k1)/zab2(k2,k3,k4,k1));

      Xpp(h3,h5) = app0 + mtsq*app2 + mtsq*mtsq*app4;  // @coverage-probe
      //--- contribution to rational part (coefficient of mt^4)
      Xrat(2,2,h3,h5) = app4;

      //----Helicity 1^- 2^+
      std::complex<double> amp2 = funcmp2(k1,k2,k3,k4,k5,k6) + funcmp2(k1,k2,k5,k6,k3,k4);

      std::complex<double> amp4 = two/(s(j1,j2)*s(k3,k4)*s(k5,k6)
             *zab2(k2,k3,k4,k1)*zab2(k2,k3,k4,k1))
          * (za(k2,k5)*zb(k1,k4)*zab2(k1,k3,k4,k2)
             - za(k1,k5)*zb(k2,k4)*zab2(k2,k3,k4,k1))
          * (za(k2,k3)*zb(k1,k6)*zab2(k1,k3,k4,k2)
             - za(k1,k3)*zb(k2,k6)*zab2(k2,k3,k4,k1));

      Xmp(h3,h5) = mtsq*amp2 + mtsq*mtsq*amp4;
      //--- contribution to rational part (coefficient of mt^4)
      Xrat(1,2,h3,h5) = amp4;
    }
  }
}

void ZZbox1LL(int j1, int j2, int j3, int j4, int j5, int j6,
              FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb,
              double mt,
              FArray2D<std::complex<double>>& Xpp, FArray2D<std::complex<double>>& Xmp,
              FArray2D<std::complex<double>>& Xpm, FArray2D<std::complex<double>>& Xmm,
              FArray4D<std::complex<double>>& Xrat) {

  // note the deliberately swapped za/zb on this first call
  ZZbox1LLcore(j1,j2,j3,j4,j5,j6,zb,za,mt,Xpp,Xmp,Xrat);
  for (int h3 = 1; h3 <= 2; ++h3) {
    for (int h5 = 1; h5 <= 2; ++h5) {
      Xpm(h3,h5) = Xmp(3-h3,3-h5);
      Xmm(h3,h5) = Xpp(3-h3,3-h5);
      Xrat(2,1,h3,h5) = Xrat(1,2,3-h3,3-h5);
      Xrat(1,1,h3,h5) = Xrat(2,2,3-h3,3-h5);
    }
  }

  ZZbox1LLcore(j1,j2,j3,j4,j5,j6,za,zb,mt,Xpp,Xmp,Xrat);
}

extern "C" {
  void ZZbox1LL_wrapper(int j1, int j2, int j3, int j4, int j5, int j6,
                        std::complex<double>* fza, std::complex<double>* fzb, double mt,
                        std::complex<double>* fXpp, std::complex<double>* fXmp,
                        std::complex<double>* fXpm, std::complex<double>* fXmm,
                        std::complex<double>* fXrat) {
    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    FArray2D<std::complex<double>> Xpp(fXpp, 2, 2);
    FArray2D<std::complex<double>> Xmp(fXmp, 2, 2);
    FArray2D<std::complex<double>> Xpm(fXpm, 2, 2);
    FArray2D<std::complex<double>> Xmm(fXmm, 2, 2);
    FArray4D<std::complex<double>> Xrat(fXrat, 2, 2, 2);
    ZZbox1LL(j1,j2,j3,j4,j5,j6,za,zb,mt,Xpp,Xmp,Xpm,Xmm,Xrat);
  }
}
EOF
