subroutine ZZbox1LL(j1,j2,j3,j4,j5,j6,za,zb,mt,Xpp,Xmp,Xpm,Xmm,Xrat)
  use, intrinsic :: iso_c_binding
  use mxpart_mod

  implicit none

  integer(c_int), intent(in) :: j1, j2, j3, j4, j5, j6
  complex(c_double_complex), dimension(mxpart,mxpart), intent(in) :: za, zb
  real(c_double), intent(in) :: mt
  complex(c_double_complex), dimension(2,2), intent(inout) :: Xpp, Xmp, Xpm, Xmm
  complex(c_double_complex), dimension(2,2,2,2), intent(inout) :: Xrat

  interface
    subroutine ZZbox1LL_wrapper(j1,j2,j3,j4,j5,j6,za,zb,mt,Xpp,Xmp,Xpm,Xmm,Xrat) &
        bind(C, name="ZZbox1LL_wrapper")
      import :: c_int, c_double, c_double_complex, mxpart
      integer(c_int), value :: j1, j2, j3, j4, j5, j6
      complex(c_double_complex), dimension(mxpart,mxpart) :: za, zb
      real(c_double), value :: mt
      complex(c_double_complex), dimension(2,2) :: Xpp, Xmp, Xpm, Xmm
      complex(c_double_complex), dimension(2,2,2,2) :: Xrat
    end subroutine ZZbox1LL_wrapper
  end interface

  call ZZbox1LL_wrapper(j1,j2,j3,j4,j5,j6,za,zb,mt,Xpp,Xmp,Xpm,Xmm,Xrat)
end subroutine ZZbox1LL
